# Check if fixed edges are consistent with a 2-coloring (bipartite)
# Fixed edges: (1,18), (4,18), (16,18), (4,19), (17,18), (11,19), (3,19)

from collections import defaultdict

fixed_edges = [(1,18), (4,18), (16,18), (4,19), (17,18), (11,19), (3,19)]

# Try to 2-color the graph with these edges
color = {}
adj = defaultdict(set)
for u, v in fixed_edges:
    adj[u].add(v)
    adj[v].add(u)

# BFS coloring
from collections import deque

def try_2color(adj, n):
    color = [-1] * n
    for start in range(n):
        if color[start] != -1:
            continue
        if start not in adj and start not in [v for u,vs in adj.items() for v in vs]:
            continue
        queue = deque([start])
        color[start] = 0
        while queue:
            node = queue.popleft()
            for nb in adj[node]:
                if color[nb] == -1:
                    color[nb] = 1 - color[node]
                    queue.append(nb)
                elif color[nb] == color[node]:
                    return None  # Not bipartite
    return color

color = try_2color(adj, 20)
print("2-coloring:", color)

# Check which vertices are colored
colored = {i: color[i] for i in range(20) if color[i] != -1}
print("Colored vertices:", colored)

# Verify triangle-free and maximality
def verify(edges, n):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check triangle-free
    for u, v in edges:
        common = adj[u] & adj[v]
        if common:
            print(f"Triangle found: {u}-{v}-{common.pop()}")
            return False

    # Check maximality: every non-edge should create a triangle
    edge_set = set(edges)
    for u in range(n):
        for v in range(u+1, n):
            if (u,v) not in edge_set:
                common = adj[u] & adj[v]
                if not common:
                    print(f"Non-edge ({u},{v}) can be added without triangle - NOT MAXIMAL")
                    return False

    print("Triangle-free: YES")
    print("Maximal: YES")
    return True

verify(edges, 20)
print("\nEdges:")
for e in edges:
    print(e)

from collections import defaultdict

A_final = [0, 1, 2, 3, 4, 5, 6, 11, 16, 17]
B_final = [7, 8, 9, 10, 12, 13, 14, 15, 18, 19]

edges = []
for a in A_final:
    for b in B_final:
        u, v = min(a,b), max(a,b)
        edges.append((u, v))
edges = sorted(set(edges))

def verify(edges, n):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for u, v in edges:
        common = adj[u] & adj[v]
        if common:
            print(f"Triangle: {u}-{v}-{common.pop()}")
            return False
    edge_set = set(edges)
    for u in range(n):
        for v in range(u+1, n):
            if (u,v) not in edge_set:
                common = adj[u] & adj[v]
                if not common:
                    print(f"Non-edge ({u},{v}) can be added - NOT MAXIMAL")
                    return False
    print("Triangle-free: YES, Maximal: YES")
    return True

verify(edges, 20)
print(f"\nTotal edges: {len(edges)}")
print("Edge list:")
for e in edges:
